@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from our community.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@category.Name</h5>
                    <p class="card-text">@category.Description</p>
                    <a href="@($"category/{category.Slug}")" class="btn btn-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static readonly CategoryInfo[] Categories =
    [
        new("Breakfast", "breakfast", "Start your day with these energizing morning meals."),
        new("Main Courses", "main-courses", "Hearty dishes for lunch and dinner."),
        new("Desserts", "desserts", "Sweet treats to satisfy your cravings."),
        new("Soups & Salads", "soups-salads", "Light and refreshing options for any season."),
        new("Appetizers", "appetizers", "Perfect starters for any gathering."),
        new("Beverages", "beverages", "Refreshing drinks and cocktails.")
    ];

    private record CategoryInfo(string Name, string Slug, string Description);
}

