namespace RecipeShare.Data;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

namespace RecipeShare.Data;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast", CategorySlug = "breakfast",
            Ingredients = ["2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder"],
            Steps = ["Mix dry ingredients.", "Whisk eggs and milk together.", "Combine wet and dry mixtures.", "Cook on griddle until golden."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast", CategorySlug = "breakfast",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice"],
            Steps = ["Toast the bread.", "Mash avocado with lemon juice, salt, and pepper.", "Spread on toast.", "Top with red pepper flakes."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Bolognese", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste"],
            Steps = ["Cook spaghetti according to package.", "Sauté onion and garlic.", "Brown the beef.", "Add tomatoes and paste, simmer 20 min.", "Serve sauce over pasta."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Breast", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["4 chicken breasts", "2 tbsp olive oil", "1 tsp paprika", "Salt and pepper", "Fresh herbs"],
            Steps = ["Marinate chicken with oil and spices for 30 min.", "Preheat grill to medium-high.", "Grill 6-7 minutes per side.", "Rest for 5 minutes before serving."],
            AverageRating = 4.0, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "2 tbsp flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold in chocolate mixture and flour.", "Bake at 200°C for 12 minutes.", "Serve immediately."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Tomato Basil Soup", Category = "Soups & Salads", CategorySlug = "soups-salads",
            Ingredients = ["6 large tomatoes", "1 onion", "3 cloves garlic", "Fresh basil", "500ml vegetable broth", "Heavy cream"],
            Steps = ["Roast tomatoes, onion, and garlic at 200°C for 25 min.", "Transfer to pot with broth.", "Simmer 15 minutes.", "Blend until smooth.", "Stir in cream and basil."],
            AverageRating = 4.3, RatingCount = 10
        },
        new()
        {
            Id = 7, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["1 baguette", "4 tomatoes", "Fresh basil", "2 cloves garlic", "Olive oil", "Balsamic vinegar"],
            Steps = ["Dice tomatoes and mix with basil, garlic, oil, and vinegar.", "Slice and toast baguette.", "Top with tomato mixture.", "Serve immediately."],
            AverageRating = 4.1, RatingCount = 7
        },
        new()
        {
            Id = 8, Title = "Iced Lemonade", Category = "Beverages", CategorySlug = "beverages",
            Ingredients = ["6 lemons", "1 cup sugar", "6 cups water", "Ice", "Fresh mint"],
            Steps = ["Make simple syrup by dissolving sugar in 1 cup hot water.", "Juice the lemons.", "Combine syrup, lemon juice, and remaining water.", "Serve over ice with mint."],
            AverageRating = 4.6, RatingCount = 18
        }
    ];

    public List<Recipe> GetByCategory(string categorySlug)
        => _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

