arguments.file_text:
@page "/category/{Slug}"

<PageTitle>@_categoryName - RecipeShare</PageTitle>

<h1>@_categoryName</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes in this category yet.</p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link mt-3">← Back to categories</a>

@code {
    [Parameter] public string Slug { get; set; } = "";

    [Inject] private RecipeShare.Data.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Data.Recipe> _recipes = [];
    private string _categoryName = "";

    private static readonly Dictionary<string, string> CategoryNames = new()
    {
        ["breakfast"] = "Breakfast",
        ["main-courses"] = "Main Courses",
        ["desserts"] = "Desserts",
        ["soups-salads"] = "Soups & Salads",
        ["appetizers"] = "Appetizers",
        ["beverages"] = "Beverages"
    };

    protected override void OnParametersSet()
    {
        _categoryName = CategoryNames.GetValueOrDefault(Slug, "Recipes");
        _recipes = RecipeService.GetByCategory(Slug);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (_recipe is null)
{
    <p class="text-danger">Recipe not found.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: @_recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h3>Rating</h3>
    <p>⭐ @_recipe.AverageRating / 5 (@_recipe.RatingCount ratings)</p>

    <StarRating RecipeId="@_recipe.Id" @rendermode="InteractiveServer" />

    <a href="@($"category/{_recipe.CategorySlug}")" class="btn btn-link mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    [Inject] private RecipeShare.Data.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Data.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="mt-2">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                disabled="@_submitted"
                title="@($"{star} star{(star > 1 ? "s" : "")}")">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }

    @if (_submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    [Inject] private RecipeShare.Data.RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_model.Title" has been added.
        <a href="@($"recipe/{_newRecipeId}")">View it here.</a>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="breakfast">Breakfast</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="soups-salads">Soups &amp; Salads</option>
                <option value="appetizers">Appetizers</option>
                <option value="beverages">Beverages</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="5" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeShare.Data.RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private static readonly Dictionary<string, string> CategoryNames = new()
    {
        ["breakfast"] = "Breakfast",
        ["main-courses"] = "Main Courses",
        ["desserts"] = "Desserts",
        ["soups-salads"] = "Soups & Salads",
        ["appetizers"] = "Appetizers",
        ["beverages"] = "Beverages"
    };

    private void HandleSubmit()
    {
        var recipe = new RecipeShare.Data.Recipe
        {
            Title = _model.Title,
            Category = CategoryNames.GetValueOrDefault(_model.Category, _model.Category),
            CategorySlug = _model.Category,
            Ingredients = _model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = _model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        _newRecipeId = recipe.Id;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or less.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one ingredient.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one step.")]
        public string Steps { get; set; } = "";
    }
}

